mapper.select:
SELECT a.artifact_id FROM biz_practical_artifact a
WHERE a.context_type = 'LESSON' AND a.context_id IN (
    #{id}
)
  AND NOT EXISTS (
    SELECT 1 FROM biz_student_answer ans
    WHERE ans.question_id = a.question_id
      AND ans.student_id = a.student_id
      AND ans.lesson_id NOT IN
      #{id}
  )

SELECT resource_path FROM biz_practical_attachment
WHERE version_id IN (
    SELECT version_id FROM biz_practical_submission_version WHERE artifact_id IN
    #{id}
) AND resource_path IS NOT NULL AND resource_path != ''
UNION
SELECT preview_path FROM biz_practical_attachment
WHERE version_id IN (
    SELECT version_id FROM biz_practical_submission_version WHERE artifact_id IN
    #{id}
) AND preview_path IS NOT NULL AND preview_path != ''

